using System.Globalization;
using System.Text;
using Sharpy.TestInfrastructure.Integration;
using Sharpy.TestInfrastructure.Oracles;
using Xunit;
using Xunit.Abstractions;

namespace Sharpy.Compiler.Tests.Properties.Differential;

/// <summary>
/// The end-to-end class guard for division by zero (#2517): <c>/</c>, <c>/=</c>, <c>**</c> and <c>**=</c> raise
/// <c>ZeroDivisionError</c> wherever CPython does, through every lowering the checker records. The cells are
/// GENERATED by crossing axes in code — operator × left operand type × right operand type × zero spelling
/// (a literal the compiler sees as a constant, a negative-zero literal, a local variable holding zero) — and
/// non-zero controls ride beside them. Every cell becomes one
/// <c>try: print(id, &lt;expr&gt;) except ZeroDivisionError as e: print(id, "ZeroDivisionError", e)</c> statement of
/// ONE program, rendered once as Sharpy (typed literals <c>1L</c>, <c>1.0f</c>, <c>1m</c>) and once as Python
/// (<c>int</c>, <c>float</c>, <c>Decimal</c>), run under both, and compared line by line.
/// </summary>
/// <remarks>
/// <para>Generated out, each a different class: <c>decimal</c> under <c>**</c> (Sharpy's decimal power is a
/// <c>float</c>, CPython's <c>Decimal(0) ** -1</c> is <c>Infinity</c>); a non-zero integer base with a negative
/// exponent (the spec's truncating <c>int ** int</c> deviation); <c>decimal</c> mixed with a float type (refused,
/// SPY0222); an augmented store whose result type is not the target's (refused, SPY0220).</para>
/// <para>Values are chosen so every non-raising result prints the same text in both languages (<c>3 / 4</c> is
/// <c>0.75</c> as float, float32 and decimal). Skips when no python3 ≥ 3.15 (the `.python-version` pin; 3.13 words the float message differently) answers, except under
/// <c>SHARPY_REQUIRE_PYTHON_ORACLE=1</c> (CI), which fails.</para>
/// </remarks>
public class ZeroDivisionDifferentialTests : IntegrationTestBase
{
    public ZeroDivisionDifferentialTests(ITestOutputHelper output) : base(output) => MuteCompilePath = true;

    private enum Kind { Int, Long, Float, Float32, Decimal }

    private enum Zero { Literal, NegativeLiteral, Variable, NonZero }

    private static readonly Kind[] Kinds = { Kind.Int, Kind.Long, Kind.Float, Kind.Float32, Kind.Decimal };

    private sealed record Cell(int Id, string Sharpy, string Python, string Label);

    private static bool IsFloat(Kind k) => k is Kind.Float or Kind.Float32;

    private static bool IsInteger(Kind k) => k is Kind.Int or Kind.Long;

    /// <summary>A numeric literal of kind <paramref name="k"/>: (Sharpy text, Python text).</summary>
    private static (string Sharpy, string Python) Lit(Kind k, int value)
    {
        var v = value.ToString(CultureInfo.InvariantCulture);
        return k switch
        {
            Kind.Int => (v, v),
            Kind.Long => (v + "L", v),
            Kind.Float => (v + ".0", v + ".0"),
            Kind.Float32 => (v + ".0f", v + ".0"),
            _ => (v + "m", "Decimal(" + v + ")"),
        };
    }

    private static string TypeName(Kind k) => k switch
    {
        Kind.Int => "int",
        Kind.Long => "int64",
        Kind.Float => "float",
        Kind.Float32 => "float32",
        _ => "decimal",
    };

    /// <summary>The zero spellings a kind has: a negative-zero literal only where it is a distinct value spelling.</summary>
    private static IEnumerable<Zero> Spellings(Kind k)
    {
        yield return Zero.Literal;
        if (!IsInteger(k))
            yield return Zero.NegativeLiteral;
        yield return Zero.Variable;
        yield return Zero.NonZero;
    }

    /// <summary>Statements that bind <c>z</c> (when needed) and the operand text for a spelling.</summary>
    private static (string SharpySetup, string PythonSetup, string Sharpy, string Python) Operand(Kind k, Zero zero, int nonZero)
    {
        var lit0 = Lit(k, 0);
        return zero switch
        {
            Zero.Literal => ("", "", lit0.Sharpy, lit0.Python),
            Zero.NegativeLiteral => ("", "", "(-" + lit0.Sharpy + ")", "(-" + lit0.Python + ")"),
            Zero.Variable => ("z: " + TypeName(k) + " = " + lit0.Sharpy, "z = " + lit0.Python, "z", "z"),
            _ => ("", "", Lit(k, nonZero).Sharpy, Lit(k, nonZero).Python),
        };
    }

    private static Kind DivisionResult(Kind l, Kind r)
    {
        if (l == Kind.Decimal || r == Kind.Decimal)
            return Kind.Decimal;
        if (l == Kind.Float || r == Kind.Float)
            return Kind.Float;
        if (l == Kind.Float32 || r == Kind.Float32)
            return Kind.Float32;
        return Kind.Float;
    }

    private static Kind? PowerResult(Kind l, Kind r)
    {
        if (l == Kind.Float || r == Kind.Float)
            return Kind.Float;
        if (l == Kind.Float32 || r == Kind.Float32)
            return Kind.Float32;
        return l == Kind.Long || r == Kind.Long ? Kind.Long : Kind.Int;
    }

    private static bool Mixable(Kind l, Kind r) =>
        !((l == Kind.Decimal && IsFloat(r)) || (r == Kind.Decimal && IsFloat(l)));

    private static List<Cell> GenerateCells()
    {
        var cells = new List<Cell>();

        void Add(string label, string sharpySetup, string pythonSetup, string sharpyStmt, string pythonStmt)
        {
            var id = cells.Count;
            cells.Add(new Cell(id, Wrap(id, sharpySetup, sharpyStmt, "e"), Wrap(id, pythonSetup, pythonStmt, "msg(e)"), label));
        }

        foreach (var l in Kinds)
        {
            foreach (var r in Kinds)
            {
                if (!Mixable(l, r))
                    continue;

                // `/`: 3 / divisor, every divisor spelling.
                foreach (var zero in Spellings(r))
                {
                    var (ss, ps, sd, pd) = Operand(r, zero, 4);
                    var three = Lit(l, 3);
                    Add($"{TypeName(l)} / {TypeName(r)} ({zero})", ss, ps,
                        "print(ID, " + three.Sharpy + " / " + sd + ")", "print(ID, " + three.Python + " / " + pd + ")");

                    // `/=`: only where the result type is the target's own type.
                    if (DivisionResult(l, r) == l)
                    {
                        Add($"{TypeName(l)} /= {TypeName(r)} ({zero})", Join(ss, "x: " + TypeName(l) + " = " + three.Sharpy),
                            Join(ps, "x = " + three.Python), "x /= " + sd + "\n        print(ID, x)", "x /= " + pd + "\n        print(ID, x)");
                    }
                }

                // `**`: a zero (or control 2) base raised to -1 and to 2; decimal is a different class.
                if (l == Kind.Decimal || r == Kind.Decimal)
                    continue;
                foreach (var zero in Spellings(l))
                {
                    var (ss, ps, sb, pb) = Operand(l, zero, 2);
                    foreach (var exponent in new[] { -1, 2 })
                    {
                        if (zero == Zero.NonZero && exponent < 0 && IsInteger(l) && IsInteger(r))
                            continue; // the truncating int ** negative deviation
                        var e = Lit(r, exponent);
                        Add($"{TypeName(l)} ** {TypeName(r)} {exponent} ({zero})", ss, ps,
                            "print(ID, " + sb + " ** " + e.Sharpy + ")", "print(ID, " + pb + " ** " + e.Python + ")");

                        // `**=`: only where the result type is the target's own type.
                        if (PowerResult(l, r) == l)
                        {
                            Add($"{TypeName(l)} **= {TypeName(r)} {exponent} ({zero})",
                                Join(ss, "x: " + TypeName(l) + " = " + sb), Join(ps, "x = " + pb),
                                "x **= " + e.Sharpy + "\n        print(ID, x)", "x **= " + e.Python + "\n        print(ID, x)");
                        }
                    }
                }
            }
        }

        return cells;
    }

    /// <summary>
    /// CPython's <c>decimal.DivisionByZero</c> (a <c>ZeroDivisionError</c>) stringifies as its signal list, not a
    /// message; the Sharpy text for every division is the spec's "division by zero".
    /// </summary>
    private const string PythonPrelude =
        "import decimal\nfrom decimal import Decimal\n\n"
        + "def msg(e):\n    return \"division by zero\" if isinstance(e, decimal.DivisionByZero) else str(e)\n\n";

    private static string Join(string a, string b) => a.Length == 0 ? b : a + "\n        " + b;

    private static string Wrap(int id, string setup, string statement, string message)
    {
        var idText = id.ToString(CultureInfo.InvariantCulture);
        var sb = new StringBuilder();
        sb.Append("def cell_").Append(idText).Append("():\n");
        sb.Append("    try:\n");
        if (setup.Length > 0)
            sb.Append("        ").Append(setup).Append('\n');
        sb.Append("        ").Append(statement.Replace("ID", idText, StringComparison.Ordinal)).Append('\n');
        sb.Append("    except ZeroDivisionError as e:\n");
        sb.Append("        print(").Append(idText).Append(", \"ZeroDivisionError\", ").Append(message).Append(")\n");
        return sb.ToString();
    }

    private static string ProgramFor(IReadOnlyList<Cell> cells, Func<Cell, string> render, string prelude)
    {
        var sb = new StringBuilder(prelude);
        foreach (var c in cells)
            sb.Append(render(c)).Append('\n');
        sb.Append("def main():\n");
        foreach (var c in cells)
            sb.Append("    cell_").Append(c.Id.ToString(CultureInfo.InvariantCulture)).Append("()\n");
        return sb.ToString();
    }

    private static Dictionary<int, string> ParseLines(string stdout)
    {
        var byId = new Dictionary<int, string>();
        foreach (var raw in stdout.Split('\n'))
        {
            var line = raw.TrimEnd('\r');
            var space = line.IndexOf(' ');
            if (space > 0 && int.TryParse(line[..space], NumberStyles.Integer, CultureInfo.InvariantCulture, out var id))
                byId[id] = line[(space + 1)..];
        }
        return byId;
    }

    /// <summary>
    /// A <c>const</c> divisor: a const known non-zero keeps the native <c>/</c>, so the division stays a C#
    /// constant in every constant position (a parameter default, a dependent const); a const that is zero
    /// raises at runtime. Generated per divisor kind; python runs the same program (consts as plain names).
    /// </summary>
    [SkippableFact]
    public void ConstNameDivisor_NonZeroStaysConstant_ZeroRaises_MatchesCPython()
    {
        var oracle = PythonBatchOracle.Over(PythonInterpreter.RequireOrSkip(minMinor: 15));
        var sharpy = new StringBuilder();
        var python = new StringBuilder(PythonPrelude);
        var calls = new List<string>();
        var cells = 0;
        foreach (var k in Kinds)
        {
            var name = TypeName(k).ToUpperInvariant();
            var four = Lit(k, 4);
            var zero = Lit(k, 0);
            var three = Lit(Kind.Int, 3);
            var result = TypeName(DivisionResult(Kind.Int, k));
            sharpy.Append("const C_").Append(name).Append(": ").Append(TypeName(k)).Append(" = ").Append(four.Sharpy).Append('\n');
            sharpy.Append("const Z_").Append(name).Append(": ").Append(TypeName(k)).Append(" = ").Append(zero.Sharpy).Append('\n');
            sharpy.Append("const DEP_").Append(name).Append(": ").Append(result).Append(" = 3 / C_").Append(name).Append('\n');
            python.Append("C_").Append(name).Append(" = ").Append(four.Python).Append('\n');
            python.Append("Z_").Append(name).Append(" = ").Append(zero.Python).Append('\n');
            python.Append("DEP_").Append(name).Append(" = 3 / C_").Append(name).Append('\n');
            foreach (var (sb, typed) in new[] { (sharpy, true), (python, false) })
            {
                sb.Append("def default_").Append(name).Append("(x").Append(typed ? ": " + result : "")
                    .Append(" = ").Append(three.Sharpy).Append(" / C_").Append(name).Append(')').Append(typed ? " -> " + result : "").Append(":\n    return x\n\n");
                sb.Append("def raise_").Append(name).Append("():\n    try:\n        print(\"").Append(name).Append(" zero\", 3 / Z_").Append(name)
                    .Append(")\n    except ZeroDivisionError as e:\n        print(\"").Append(name).Append(" zero ZeroDivisionError\", ")
                    .Append(typed ? "e" : "msg(e)").Append(")\n\n");
            }
            calls.Add("    print(\"" + name + " default\", default_" + name + "())");
            calls.Add("    print(\"" + name + " dependent\", DEP_" + name + ")");
            calls.Add("    raise_" + name + "()");
            cells += 3;
        }
        var main = "def main():\n" + string.Join("\n", calls) + "\n";
        var sharpySource = sharpy + "\n" + main;
        var pythonSource = python + "\n" + main + "\nmain()\n";

        var py = oracle.RunBatch(new[] { new PyRequest(0, pythonSource) });
        Assert.True(py.TryGetValue(0, out var pyResult) && pyResult.Ok,
            "python3 did not run the const-divisor matrix: " + (pyResult?.Stderr ?? "no verdict"));
        var run = CompileAndExecute(sharpySource, "zero_division_const_matrix.spy", executionTimeoutMs: 60_000);
        Assert.True(RanToCompletion(run), JudgeRun(run, sharpySource, "Sharpy const-divisor matrix") ?? "timed out");

        var expected = pyResult!.Stdout.Replace("\r", "", StringComparison.Ordinal).TrimEnd();
        var actual = run.StandardOutput.Replace("\r", "", StringComparison.Ordinal).TrimEnd();
        Assert.Equal(cells, expected.Split('\n').Length);
        Assert.Contains("ZeroDivisionError division by zero", expected, StringComparison.Ordinal);
        Assert.Equal(expected, actual);
    }

    /// <summary>
    /// A const whose initializer divides by a non-zero const is a C# constant, so it reads as a <c>case</c>
    /// constant (Sharpy's const-name value pattern; python has no twin, a bare name there captures).
    /// </summary>
    [Fact]
    public void ConstNameDivisor_DependentConstAsMatchCase_StaysConstant()
    {
        var source = "const S: float = 4.0\nconst Q: float = 1.0 / S\n\ndef main():\n    v: float = 0.25\n"
            + "    match v:\n        case Q:\n            print(\"hit\")\n        case _:\n            print(\"miss\")\n";
        var run = CompileAndExecute(source, "zero_division_const_case.spy");
        Assert.True(RanToCompletion(run), JudgeRun(run, source, "const-divisor match case") ?? "timed out");
        Assert.Equal("hit", run.StandardOutput.Trim());
    }

    /// <summary>
    /// The const divisor across the import boundary: module <c>a</c> exports <c>SCALE</c> and <c>ZERO</c>;
    /// module <c>main</c> divides by them qualified (<c>a.SCALE</c>) and imported by name (<c>from a import</c>).
    /// A non-zero imported const stays a C# constant (a parameter default compiles), a zero one raises at
    /// runtime, as python does (python3.15: <c>0.25</c> twice, then <c>ZeroDivisionError division by zero</c>).
    /// </summary>
    [Fact]
    public void ConstNameDivisor_AcrossModules_NonZeroStaysConstant_ZeroRaises()
    {
        using var helper = new Helpers.ProjectCompilationHelper(Output);
        helper.AddSourceFile("a.spy", "const SCALE: float = 4.0\nconst ZERO: float = 0.0\n");
        helper.AddSourceFile("main.spy",
            "import a\nfrom a import SCALE, ZERO\n\n"
            + "def f(x: float = 1.0 / a.SCALE) -> float:\n    return x\n\n"
            + "def g(x: float = 1.0 / SCALE) -> float:\n    return x\n\n"
            + "def main() -> None:\n    print(f())\n    print(g())\n"
            + "    try:\n        print(1.0 / a.ZERO)\n    except ZeroDivisionError as e:\n        print(\"ZeroDivisionError\", e)\n");
        var run = CompileAndExecuteEntryFile(Path.Combine(helper.SourceDirectory, "main.spy"));
        Assert.True(RanToCompletion(run), JudgeRun(run, "main.spy", "cross-module const divisor") ?? "timed out");
        Assert.Equal("0.25\n0.25\nZeroDivisionError division by zero",
            run.StandardOutput.Replace("\r", "", StringComparison.Ordinal).Trim());
    }

    /// <summary>A parameter default dividing by an imported const that IS zero is refused (SPY0401).</summary>
    [Fact]
    public void ConstNameDivisor_AcrossModules_ZeroInParameterDefault_IsRefused()
    {
        using var helper = new Helpers.ProjectCompilationHelper(Output);
        helper.AddSourceFile("a.spy", "const ZERO: float = 0.0\n");
        helper.AddSourceFile("main.spy",
            "import a\n\ndef g(x: float = 1.0 / a.ZERO) -> float:\n    return x\n\ndef main() -> None:\n    print(g())\n");
        var run = CompileAndExecuteEntryFile(Path.Combine(helper.SourceDirectory, "main.spy"));
        Assert.Contains(run.RawDiagnostics, d => d.IsError && d.Code == "SPY0401");
    }

    // ── A float32 const narrowed from an unsuffixed literal (float_literals.md, Narrowing) ────────────────

    /// <summary>How a test program reaches <c>T</c>/<c>U</c>: declared in main, <c>from a import</c>, or <c>a.T</c>.</summary>
    public static IEnumerable<object[]> NarrowedConstRoutes() => new[]
    {
        new object[] { "SameModule" }, new object[] { "FromImport" }, new object[] { "Qualified" },
    };

    private const string NarrowedConsts = "const T: float32 = 1e-46\nconst U: float32 = 1e-30\n";

    private ExecutionResult RunNarrowed(string route, string body)
    {
        using var helper = new Helpers.ProjectCompilationHelper(Output);
        string prefix;
        string t, u;
        switch (route)
        {
            case "SameModule":
                prefix = NarrowedConsts + "\n";
                (t, u) = ("T", "U");
                break;
            case "FromImport":
                helper.AddSourceFile("a.spy", NarrowedConsts);
                prefix = "from a import T, U\n\n";
                (t, u) = ("T", "U");
                break;
            default:
                helper.AddSourceFile("a.spy", NarrowedConsts);
                prefix = "import a\n\n";
                (t, u) = ("a.T", "a.U");
                break;
        }
        helper.AddSourceFile("main.spy", prefix + body.Replace("{T}", t, StringComparison.Ordinal).Replace("{U}", u, StringComparison.Ordinal));
        return CompileAndExecuteEntryFile(Path.Combine(helper.SourceDirectory, "main.spy"));
    }

    /// <summary>
    /// <c>const T: float32 = 1e-46</c> is <c>0f</c> at run time, so <c>1.0 / T</c> raises (never inf), while
    /// <c>U = 1e-30</c> is non-zero in float32 and stays a C# constant divisor (its default compiles).
    /// </summary>
    [Theory]
    [MemberData(nameof(NarrowedConstRoutes))]
    public void NarrowedFloat32Const_ZeroRaises_NonZeroStaysConstant(string route)
    {
        var run = RunNarrowed(route,
            "def g(x: float = 1.0 / {U}) -> float:\n    return x\n\n"
            + "def main() -> None:\n    print(g() > 0.0)\n"
            + "    try:\n        print(1.0 / {T})\n    except ZeroDivisionError as e:\n        print(\"ZeroDivisionError\", e)\n");
        Assert.True(RanToCompletion(run), JudgeRun(run, route, "narrowed float32 const") ?? "timed out");
        Assert.Equal("True\nZeroDivisionError division by zero",
            run.StandardOutput.Replace("\r", "", StringComparison.Ordinal).Trim());
    }

    /// <summary>
    /// A division by the narrowed-to-zero <c>T</c> is no C# constant: as a parameter default it is refused, and a
    /// const built from it is no constant either, so a default reading that const is refused too.
    /// </summary>
    [Theory]
    [MemberData(nameof(NarrowedConstRoutes))]
    public void NarrowedFloat32Const_ZeroDivisorIsNoConstant(string route)
    {
        var run = RunNarrowed(route,
            "const INV: float = 1.0 / {T}\n\n"
            + "def f(x: float = 1.0 / {T}) -> float:\n    return x\n\n"
            + "def h(x: float = INV) -> float:\n    return x\n\n"
            + "def main() -> None:\n    print(f(), h())\n");
        Assert.Equal(2, run.RawDiagnostics.Count(d => d.IsError && d.Code == "SPY0401"));
    }

    // ── Float arithmetic in a divisor ─────────────────────────────────────────────────────────────────────

    /// <summary>
    /// <c>+ - *</c> over float constants fold, each step in its operand type's precision, so a divisor known
    /// non-zero stays a C# constant (python3.15 prints the same three values); <c>A - A</c> folds to zero and is
    /// refused.
    /// </summary>
    [SkippableFact]
    public void FloatArithmeticDivisor_FoldsAndStaysConstant_MatchesCPython()
    {
        var oracle = PythonBatchOracle.Over(PythonInterpreter.RequireOrSkip(minMinor: 15));
        const string defs = "def f1(x: float = 1.0 / (2.0 + 1.0)) -> float:\n    return x\n\n"
            + "def f2(x: float = 1.0 / (A + B)) -> float:\n    return x\n\n"
            + "def f3(x: float = 1.0 / (S * 2.0)) -> float:\n    return x\n\n"
            + "def f4(x: float = D) -> float:\n    return x\n\n"
            + "def main():\n    print(f1())\n    print(f2())\n    print(f3())\n    print(f4())\n";
        var sharpy = "const A: float = 1.0\nconst B: float = 2.0\nconst S: float = 4.0\nconst D: float = 1.0 / (A + B)\n\n" + defs;
        var python = "A = 1.0\nB = 2.0\nS = 4.0\nD = 1.0 / (A + B)\n\n"
            + defs.Replace(": float", "", StringComparison.Ordinal).Replace(" -> float", "", StringComparison.Ordinal) + "\nmain()\n";

        var py = oracle.RunBatch(new[] { new PyRequest(0, python) });
        Assert.True(py.TryGetValue(0, out var pyResult) && pyResult.Ok, "python3 did not run: " + (pyResult?.Stderr ?? "no verdict"));
        var run = CompileAndExecute(sharpy, "zero_division_float_fold.spy");
        Assert.True(RanToCompletion(run), JudgeRun(run, sharpy, "float-arithmetic divisor") ?? "timed out");
        Assert.Equal(pyResult!.Stdout.Replace("\r", "", StringComparison.Ordinal).Trim(),
            run.StandardOutput.Replace("\r", "", StringComparison.Ordinal).Trim());
    }

    /// <summary>
    /// A divisor whose fold is zero is refused as a default: <c>A - A</c>, and a float32 product that underflows
    /// to zero in float32 (<c>1e-30f * 1e-30f</c>; the float64 product would be 1e-60). At run time the same
    /// float32 division raises.
    /// </summary>
    [Fact]
    public void FloatArithmeticDivisor_FoldingToZero_IsRefused_AndRaises()
    {
        var refused = CompileAndExecute(
            "const A: float = 1.0\nconst P: float32 = 1e-30f\nconst Q: float32 = 1e-30f\n\n"
            + "def f(x: float = 1.0 / (A - A)) -> float:\n    return x\n\n"
            + "def g(x: float32 = 1.0f / (P * Q)) -> float32:\n    return x\n\n"
            + "def main():\n    print(f(), g())\n", "zero_division_float_fold_zero.spy");
        Assert.Equal(2, refused.RawDiagnostics.Count(d => d.IsError && d.Code == "SPY0401"));

        var source = "const P: float32 = 1e-30f\nconst Q: float32 = 1e-30f\n\ndef main():\n"
            + "    try:\n        print(1.0f / (P * Q))\n    except ZeroDivisionError as e:\n        print(\"ZeroDivisionError\", e)\n";
        var run = CompileAndExecute(source, "zero_division_float32_underflow.spy");
        Assert.True(RanToCompletion(run), JudgeRun(run, source, "float32 underflow divisor") ?? "timed out");
        Assert.Equal("ZeroDivisionError division by zero", run.StandardOutput.Trim());
    }

    /// <summary>
    /// An integer operand in a float32 step is converted to float32 BEFORE the operation, as the emitted C#
    /// does: <c>16777217 - P</c> with <c>P = 16777216.0f</c> is <c>16777216f - 16777216f = 0f</c>, so the division
    /// raises and the default is refused; <c>16777218 - P</c> is exactly 2 and stays a constant.
    /// </summary>
    [Fact]
    public void Float32StepWithIntegerOperand_ConvertsTheIntegerFirst()
    {
        const string consts = "const P: float32 = 16777216.0f\n\n";
        var refused = CompileAndExecute(consts
            + "def f(x: float32 = 1.0f / (16777217 - P)) -> float32:\n    return x\n\ndef main():\n    print(f())\n",
            "zero_division_f32_int_refused.spy");
        Assert.Contains(refused.RawDiagnostics, d => d.IsError && d.Code == "SPY0401");

        var source = consts
            + "def g(x: float32 = 1.0f / (16777218 - P)) -> float32:\n    return x\n\n"
            + "def main():\n    print(g())\n"
            + "    try:\n        print(1.0f / (16777217 - P))\n    except ZeroDivisionError as e:\n        print(\"ZeroDivisionError\", e)\n";
        var run = CompileAndExecute(source, "zero_division_f32_int.spy");
        Assert.True(RanToCompletion(run), JudgeRun(run, source, "float32 step with an integer operand") ?? "timed out");
        Assert.Equal("0.5\nZeroDivisionError division by zero",
            run.StandardOutput.Replace("\r", "", StringComparison.Ordinal).Trim());
    }

    /// <summary>
    /// Positive control for the const rule: a parameter default dividing by a const that IS zero is not a
    /// constant expression (CPython raises at definition time), so it is refused, never folded to inf.
    /// </summary>
    [Fact]
    public void ConstNameDivisor_ZeroInParameterDefault_IsRefused()
    {
        var source = "const ZERO: float = 0.0\n\ndef f(x: float = 1.0 / ZERO) -> float:\n    return x\n\ndef main():\n    print(f())\n";
        var run = CompileAndExecute(source, "zero_division_const_default.spy");
        Assert.Contains(run.RawDiagnostics, d => d.IsError && d.Code == "SPY0401");
    }

    [SkippableFact]
    public void DivisionAndPowerByZero_OperatorTypeSpellingMatrix_MatchesCPython()
    {
        var oracle = PythonBatchOracle.Over(PythonInterpreter.RequireOrSkip(minMinor: 15));
        var cells = GenerateCells();

        var pythonSource = ProgramFor(cells, c => c.Python, PythonPrelude) + "\nmain()\n";
        var py = oracle.RunBatch(new[] { new PyRequest(0, pythonSource) });
        Assert.True(py.TryGetValue(0, out var pyResult) && pyResult.Ok,
            "python3 did not run the division matrix: " + (pyResult?.Stderr ?? "no verdict"));
        var pythonById = ParseLines(pyResult!.Stdout);
        Assert.Equal(cells.Count, pythonById.Count);

        var sharpySource = ProgramFor(cells, c => c.Sharpy, "");
        var run = CompileAndExecute(sharpySource, "zero_division_matrix.spy", executionTimeoutMs: 60_000);
        Assert.True(RanToCompletion(run), JudgeRun(run, sharpySource, "Sharpy division matrix") ?? "timed out");
        var sharpyById = ParseLines(run.StandardOutput);

        var divergences = new List<string>();
        foreach (var cell in cells)
        {
            var expected = pythonById[cell.Id];
            var actual = sharpyById.TryGetValue(cell.Id, out var s) ? s : "<no line>";
            if (!string.Equals(expected, actual, StringComparison.Ordinal))
                divergences.Add($"  #{cell.Id} {cell.Label}: python `{expected}`, sharpy `{actual}`");
        }

        // Positive controls: both messages and the non-raising arm are reached, and every operator family has a
        // raising cell, so the matrix cannot pass over a zero-free or an all-raising axis.
        Assert.Contains(cells, c => pythonById[c.Id] == "ZeroDivisionError division by zero");
        Assert.Contains(cells, c => pythonById[c.Id] == "ZeroDivisionError zero to a negative power");
        Assert.Contains(cells, c => !pythonById[c.Id].StartsWith("ZeroDivisionError", StringComparison.Ordinal));
        foreach (var op in new[] { " / ", " /= ", " ** ", " **= " })
            Assert.Contains(cells, c => c.Label.Contains(op, StringComparison.Ordinal)
                && pythonById[c.Id].StartsWith("ZeroDivisionError", StringComparison.Ordinal));

        Assert.True(divergences.Count == 0,
            $"{divergences.Count} of {cells.Count} division/power cells diverge from CPython:\n" + string.Join("\n", divergences));
    }
}
